$pdo = db();
$out = [];
$ok = function (string $url): bool {
    $h = @get_headers($url, true);
    return is_array($h) && str_contains((string)($h[0] ?? ''), '200');
};
$carExists = $pdo->prepare("SELECT id FROM social_posts WHERE tipo='carousel' AND imagem_url=? LIMIT 1");
$carIns = $pdo->prepare("INSERT INTO social_posts (canal,tipo,midia_tipo,legenda,imagem_url,carousel_urls,agendado_para,status) VALUES ('instagram','carousel','imagem',?,?,?,?,'pendente')");
foreach ($plan['carrosseis'] as $c) {
    $missing = array_values(array_filter($c['urls'], fn($u) => !$ok($u)));
    if ($missing) { $out[] = "CARROSSEL|MIDIA_ERRO|{$c['when']}|" . basename(dirname($missing[0])) . '/' . basename($missing[0]); continue; }
    $carExists->execute([$c['urls'][0]]);
    if ($carExists->fetchColumn()) { $out[] = "CARROSSEL|IGNORADO|{$c['when']}"; continue; }
    $carIns->execute([$c['caption'], $c['urls'][0], json_encode($c['urls'], JSON_UNESCAPED_SLASHES), $c['when']]);
    $out[] = "CARROSSEL|OK|id={$pdo->lastInsertId()}|{$c['when']}|" . count($c['urls']) . " slides";
}
$stExists = $pdo->prepare("SELECT id FROM social_posts WHERE tipo='story' AND imagem_url=? LIMIT 1");
$stIns = $pdo->prepare("INSERT INTO social_posts (canal,tipo,midia_tipo,legenda,imagem_url,link_url,agendado_para,status) VALUES ('instagram','story','imagem','',?,NULL,?,'pendente')");
foreach ($plan['stories'] as $s) {
    $url = 'https://media.techsantos.com.br/' . $s['file'];
    if (!$ok($url)) { $out[] = "STORY|MIDIA_ERRO|{$s['file']}"; continue; }
    $stExists->execute([$url]);
    if ($stExists->fetchColumn()) { $out[] = "STORY|IGNORADO|{$s['file']}"; continue; }
    $stIns->execute([$url, $s['when']]);
    $out[] = "STORY|OK|id={$pdo->lastInsertId()}|{$s['when']}|" . basename($s['file']);
}
header('Content-Type: text/plain; charset=utf-8');
echo implode("
", $out) . "
";
